CREATE TABLE workspace_closing_settings (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, source_mappings JSONB NOT NULL DEFAULT '{}'::jsonb, customer_aliases JSONB NOT NULL DEFAULT '{}'::jsonb, vendor_aliases JSONB NOT NULL DEFAULT '{}'::jsonb, categories JSONB NOT NULL DEFAULT '{}'::jsonb, bank_rules JSONB NOT NULL DEFAULT '[]'::jsonb, fiscal_period JSONB NOT NULL DEFAULT '{}'::jsonb, calculation_preferences JSONB NOT NULL DEFAULT '{}'::jsonb, approval_preferences JSONB NOT NULL DEFAULT '{}'::jsonb, selected_report_template_id INTEGER, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
