CREATE TABLE monthly_closing_runs (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, period VARCHAR(20) NOT NULL, upload_ids JSONB NOT NULL DEFAULT '[]'::jsonb, calculation_id INTEGER REFERENCES calculation_versions(id) ON DELETE SET NULL, reconciliation_run_id INTEGER REFERENCES reconciliation_runs(id) ON DELETE SET NULL, idempotency_key VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL, progress JSONB NOT NULL DEFAULT '{}'::jsonb, rules_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb, exceptions JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMPTZ, CONSTRAINT uq_monthly_closing_idempotency UNIQUE(user_id,idempotency_key));
CREATE INDEX ix_monthly_closing_runs_user_id ON monthly_closing_runs(user_id); CREATE INDEX ix_monthly_closing_runs_period ON monthly_closing_runs(period);
