CREATE TABLE monthly_closing_audit_events (id SERIAL PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES monthly_closing_runs(id) ON DELETE CASCADE, actor_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, action VARCHAR(40) NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- ledgerly:statement-break
CREATE TABLE report_templates (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, business_name VARCHAR(160) NOT NULL, logo_data TEXT, brand_color VARCHAR(12) NOT NULL DEFAULT '#7357FF', language VARCHAR(8) NOT NULL DEFAULT 'en', sections JSONB NOT NULL DEFAULT '[]'::jsonb, selected_kpis JSONB NOT NULL DEFAULT '[]'::jsonb, selected_charts JSONB NOT NULL DEFAULT '[]'::jsonb, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_report_templates_user_id ON report_templates(user_id);
-- ledgerly:statement-break
CREATE TABLE report_snapshots (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, template_id INTEGER NOT NULL REFERENCES report_templates(id) ON DELETE CASCADE, calculation_id INTEGER NOT NULL REFERENCES calculation_versions(id) ON DELETE CASCADE, period VARCHAR(20) NOT NULL, content JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- ledgerly:statement-break
CREATE TABLE report_shares (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, report_id INTEGER NOT NULL REFERENCES report_snapshots(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_report_shares_token_hash ON report_shares(token_hash);
